<script>(()=>{const p=document.getElementById('password'),b=document.getElementById('show-pass');b.addEventListener('click',()=>{p.type=p.type==='password'?'text':'password';b.textContent=p.type==='password'?'Show':'Hide';});const wipe=document.getElementById('page-wipe'),root=document.documentElement,key='scholarhunt-page-transition';if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;let nav=false;if(root.classList.contains('sh-arriving')){try{sessionStorage.removeItem(key)}catch(_){}requestAnimationFrame(()=>requestAnimationFrame(()=>{root.classList.remove('sh-arriving');wipe.classList.add('is-entering');}));}document.querySelectorAll('a[href]').forEach(a=>a.addEventListener('click',e=>{if(nav||e.defaultPrevented||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0||a.target==='_blank')return;const t=new URL(a.href,location.href);if(t.origin!==location.origin||t.pathname!=='/'||location.pathname!=='/login')return;e.preventDefault();nav=true;root.classList.add('sh-down');wipe.style.transition='none';wipe.classList.remove('is-leaving','is-entering');void wipe.offsetHeight;wipe.style.transition='';try{sessionStorage.setItem(key,'down')}catch(_){}requestAnimationFrame(()=>requestAnimationFrame(()=>{wipe.classList.add('is-leaving');setTimeout(()=>location.assign(t.href),735)}));}));window.addEventListener('pageshow',e=>{if(e.persisted){root.classList.remove('sh-arriving');wipe.classList.remove('is-leaving','is-entering');nav=false}});})();</script></body></html>
